// Qué mide el panel por marca. Edita aquí los eventos de GA4:
// lead: el evento que cuenta como «dejó sus datos»; medio: un paso intermedio del embudo (o null si no tienes).
const MARCAS = {
  'marca-a': { nombre: 'Marca A', dominio: '__DOMINIO_A__', ga4: '__GA4_PROPIEDAD_A__', gsc: '__GSC_SITIO_A__',
    lead: { nombre: 'generate_lead', etiqueta: 'Dejaron sus datos' }, medio: { nombre: 'form_start', etiqueta: 'Empezaron el formulario' } },
  'marca-b': { nombre: 'Marca B', dominio: '__DOMINIO_B__', ga4: '__GA4_PROPIEDAD_B__', gsc: '__GSC_SITIO_B__',
    lead: { nombre: 'generate_lead', etiqueta: 'Dejaron sus datos' }, medio: { nombre: 'form_start', etiqueta: 'Empezaron el formulario' } },
};
const q = ($('Panel analytics').first().json.query || {});
const dias = Math.min(90, Math.max(7, Number(q.dias) || 28));
const hoy = $now.setZone('America/Mexico_City').startOf('day');
const f = n => hoy.minus({ days: n }).toISODate();
const R = { dias, desde: f(dias), hasta: f(1), ant_desde: f(dias * 2), ant_hasta: f(dias + 1) };
const rangos = [{ startDate: R.desde, endDate: R.hasta, name: 'actual' }, { startDate: R.ant_desde, endDate: R.ant_hasta, name: 'anterior' }];
const out = [];
for (const [marca, c] of Object.entries(MARCAS)) {
  const ga = 'https://analyticsdata.googleapis.com/v1beta/properties/' + c.ga4 + ':batchRunReports';
  out.push({ json: { marca, tipo: 'ga4', url: ga, body: { requests: [
    { dateRanges: rangos, dimensions: [{ name: 'date' }], metrics: [{ name: 'sessions' }, { name: 'engagedSessions' }], limit: 400 },
    { dateRanges: rangos, metrics: [{ name: 'sessions' }, { name: 'engagedSessions' }, { name: 'activeUsers' }] },
    { dateRanges: rangos, dimensions: [{ name: 'sessionDefaultChannelGroup' }], metrics: [{ name: 'sessions' }, { name: 'engagedSessions' }], limit: 30 },
    { dateRanges: [rangos[0]], dimensions: [{ name: 'landingPage' }], metrics: [{ name: 'sessions' }], orderBys: [{ metric: { metricName: 'sessions' }, desc: true }], limit: 30 },
    { dateRanges: rangos, dimensions: [{ name: 'eventName' }], metrics: [{ name: 'eventCount' }], limit: 60 },
  ] } } });
  // Atribución aparte: si GA4 rechaza la combinación, lo demás sigue funcionando.
  out.push({ json: { marca, tipo: 'atribucion', url: ga, body: { requests: [
    { dateRanges: [rangos[0]], dimensions: [{ name: 'firstUserDefaultChannelGroup' }, { name: 'sessionDefaultChannelGroup' }], metrics: [{ name: 'eventCount' }],
      dimensionFilter: { filter: { fieldName: 'eventName', stringFilter: { matchType: 'EXACT', value: c.lead.nombre } } }, limit: 100 },
  ] } } });
  const sc = 'https://www.googleapis.com/webmasters/v3/sites/' + encodeURIComponent(c.gsc) + '/searchAnalytics/query';
  out.push({ json: { marca, tipo: 'gsc_dia', url: sc, body: { startDate: R.ant_desde, endDate: R.hasta, dimensions: ['date'], rowLimit: 400 } } });
  out.push({ json: { marca, tipo: 'gsc_q', url: sc, body: { startDate: R.desde, endDate: R.hasta, dimensions: ['query'], rowLimit: 30 } } });
  out.push({ json: { marca, tipo: 'gsc_p', url: sc, body: { startDate: R.desde, endDate: R.hasta, dimensions: ['page'], rowLimit: 30 } } });
}
return out.map(o => ({ json: Object.assign(o.json, { R, MARCAS }) }));

// Lo que leen Resultados, Analytics y SEO. Sin datos de contacto.
const C = $('Configuración').all().map(i => i.json);
const G = $('Google').all().map(i => i.json || {});
const { R, MARCAS } = C[0];
const err = j => (j && j.error) ? String(j.error.message || j.error.status || JSON.stringify(j.error)).slice(0, 300) : '';
const iso = s => s.length === 8 ? s.slice(0, 4) + '-' + s.slice(4, 6) + '-' + s.slice(6) : s;
const leer = n => { try { return $(n).first().json || {}; } catch (e) { return { error: { message: 'no corrió' } }; } };
const out = { generado: $now.setZone('America/Mexico_City').toFormat('yyyy-MM-dd HH:mm'), dias: R.dias, desde: R.desde, hasta: R.hasta, ant_desde: R.ant_desde, ant_hasta: R.ant_hasta,
  sheet_url: 'https://docs.google.com/spreadsheets/d/__SHEET_ID__/edit', marcas: {}, seo: {} };
for (const [m, c] of Object.entries(MARCAS)) {
  out.marcas[m] = { nombre: c.nombre, dominio: c.dominio, lead: c.lead, medio: c.medio,
    ga4_url: 'https://analytics.google.com/analytics/web/#/p' + c.ga4 + '/reports/intelligenthome',
    gsc_url: 'https://search.google.com/search-console/performance/search-analytics?resource_id=' + encodeURIComponent(c.gsc),
    ga4: { error: '' }, gsc: { error: '' }, meta: {}, leads_sheet: { total: 0, clientes: 0, medido: false } };
}
C.forEach((p, i) => {
  const j = G[i] || {}, M = out.marcas[p.marca]; if (!M) return;
  const e = err(j);
  if (p.tipo === 'ga4') {
    if (e || !j.reports) { M.ga4.error = e || 'GA4 no devolvió reportes'; return; }
    const [dia, tot, can, pag, ev] = j.reports;
    const rango = r => r.dimensionValues.at(-1).value;
    const g = M.ga4;
    g.diario = {}; g.diario_ant = {};
    for (const r of dia.rows || []) (rango(r) === 'actual' ? g.diario : g.diario_ant)[iso(r.dimensionValues[0].value)] = { s: +r.metricValues[0].value, e: +r.metricValues[1].value };
    const T = { actual: [0, 0, 0], anterior: [0, 0, 0] };
    for (const r of tot.rows || []) T[rango(r)] = r.metricValues.map(x => +x.value);
    [g.sesiones, g.enganchadas, g.usuarios] = T.actual; [g.sesiones_ant, g.enganchadas_ant, g.usuarios_ant] = T.anterior;
    const ch = {};
    for (const r of can.rows || []) { const k = r.dimensionValues[0].value; const x = ch[k] = ch[k] || { canal: k, s: 0, s_ant: 0, e: 0 }; if (rango(r) === 'actual') { x.s += +r.metricValues[0].value; x.e += +r.metricValues[1].value; } else x.s_ant += +r.metricValues[0].value; }
    g.canales = Object.values(ch).sort((a, b) => b.s - a.s);
    g.paginas = (pag.rows || []).map(r => ({ pagina: r.dimensionValues[0].value, s: +r.metricValues[0].value }));
    g.eventos = {};
    for (const r of ev.rows || []) { const k = r.dimensionValues[0].value; g.eventos[k] = g.eventos[k] || [0, 0]; g.eventos[k][rango(r) === 'actual' ? 0 : 1] += +r.metricValues[0].value; }
  } else if (p.tipo === 'atribucion') {
    if (e || !j.reports) { M.ga4.atribucion_error = e || 'sin datos'; M.ga4.atribucion = []; return; }
    M.ga4.atribucion = (j.reports[0].rows || []).map(r => ({ primero: r.dimensionValues[0].value, ultimo: r.dimensionValues[1].value, n: +r.metricValues[0].value }));
  } else if (p.tipo === 'gsc_dia') {
    if (e) { M.gsc.error = e; return; }
    const s = M.gsc; s.diario = {}; s.clics = s.impresiones = s.clics_ant = s.impresiones_ant = 0; let pw = 0;
    for (const r of j.rows || []) {
      const d = r.keys[0];
      if (d >= R.desde) { s.diario[d] = { c: r.clicks, i: r.impressions }; s.clics += r.clicks; s.impresiones += r.impressions; pw += r.position * r.impressions; }
      else { s.clics_ant += r.clicks; s.impresiones_ant += r.impressions; }
    }
    s.posicion = s.impresiones ? Math.round(pw / s.impresiones * 10) / 10 : null;
  } else if (p.tipo === 'gsc_q') {
    M.gsc.consultas = e ? [] : (j.rows || []).map(r => ({ q: r.keys[0], c: r.clicks, i: r.impressions, pos: Math.round(r.position * 10) / 10 }));
  } else if (p.tipo === 'gsc_p') {
    M.gsc.paginas = e ? [] : (j.rows || []).map(r => ({ url: r.keys[0], c: r.clicks, i: r.impressions, pos: Math.round(r.position * 10) / 10 }));
  }
});
// Meta: impresiones de anuncios y alcance de la página por día.
for (const [m, L] of [['marca-a', 'A'], ['marca-b', 'B']]) {
  const M = out.marcas[m]; if (!M) continue;
  const a = leer('Anuncios ' + L), p = leer('Página ' + L);
  M.meta = { anuncios: {}, pagina: {}, error_anuncios: err(a), error_pagina: err(p) };
  for (const r of a.data || []) M.meta.anuncios[r.date_start] = +r.impressions || 0;
  for (const s of p.data || []) for (const v of s.values || []) { const d = String(v.end_time || '').slice(0, 10); if (d) M.meta.pagina[d] = (+v.value || 0); }
}
// Leads del Sheet: total y clientes (columna estado = cliente, ganado o venta).
let leads = []; try { leads = $('Leads').all().map(i => i.json || {}); } catch (e) {}
for (const l of leads) {
  const M = out.marcas[l.marca]; if (!M || !l.lead_id || String(l.fecha || '').slice(0, 10) < R.desde || l.estado === 'descartado') continue;
  M.leads_sheet.total++;
  if (/cliente|ganad|venta|vendid|cerrad/i.test(String(l.estado || ''))) M.leads_sheet.clientes++;
}
for (const l of leads) { const M = out.marcas[l.marca]; if (M && /cliente|ganad|venta|vendid|cerrad/i.test(String(l.estado || ''))) M.leads_sheet.medido = true; }
// Pestañas SEO del Sheet (las escribe «SEO posiciones y on-page»).
const S = leer('Pestañas SEO');
if (err(S) || !S.valueRanges) out.seo = { error: err(S) || 'Faltan las pestañas SEO: corre «SEO preparar pestañas (manual)».', posiciones: [], paginas: [], propuestas: [] };
else {
  const [pos, onp, prop] = S.valueRanges.map(v => (v.values || []).slice(1));
  const fp = pos.reduce((a, r) => r[0] > a ? r[0] : a, '');
  out.seo.fecha_pos = fp;
  out.seo.posiciones = pos.filter(r => r[0] === fp).map(r => ({ marca: r[2], keyword: r[3], volumen: r[5] === '' || r[5] == null ? null : +r[5], posicion: r[6] === '' || r[6] == null ? null : +r[6], anterior: r[7] === '' || r[7] == null ? null : +r[7], cambio: r[8] || '', url: r[9] || '' }));
  const fo = onp.reduce((a, r) => r[0] > a ? r[0] : a, '');
  out.seo.fecha_onpage = fo;
  out.seo.paginas = onp.filter(r => r[0] === fo && r[13] && r[13] !== 'ok').map(r => ({ marca: r[2], url: r[3], prioridad: r[13], problemas: r[12] || '' }));
  out.seo.propuestas = prop.map((r, k) => ({ fila: k + 2, fecha: r[0], marca: r[2], url: r[3], cambio: r[4], actual: r[5] || '', propuesta: r[6] || '', por_que: r[7] || '', estado: r[8] || '' })).filter(x => x.estado === 'propuesto');
}
return [{ json: out }];
